        @if (_loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast message -->
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") alert-dismissible fade show toast-message" role="alert">
                    @_toastMessage
                    <button type="button" class="btn-close" @onclick="() => _toastMessage = null"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

<!-- Session revoke confirmation modal -->
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
                    <p class="text-muted mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @if (_revoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    // --- Section definitions ---
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelMuteState> _channels = new();

    private class ChannelMuteState
    {
        public string Name { get; set; } = "";
        public bool Muted { get; set; }
    }

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _availableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean" };

    // Known channels for the mute list
    private readonly string[] _allChannels = { "general", "announcements", "engineering", "design", "marketing", "random", "support" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllDataAsync();
        _loading = false;
    }

    private async Task LoadAllDataAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        LoadProfileState(await profileTask);
        LoadNotificationState(await notifTask);
        _securitySettings = await securityTask;
        LoadAppearanceState(await appearanceTask);
    }

    // ===================== PROFILE =====================

    private void LoadProfileState(UserProfile profile)
    {
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private bool ProfileHasChanges =>
        _savedProfile is not null &&
        (_displayName != _savedProfile.DisplayName ||
         _email != _savedProfile.Email ||
         _avatarUrl != _savedProfile.AvatarUrl ||
         _bio != _savedProfile.Bio);

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            LoadProfileState(_savedProfile);
        }
    }

    private RenderFragment RenderProfile() => __builder =>
    {
        <h3 class="section-title">Profile</h3>

        <div class="card settings-card">
            <div class="card-body">
                <!-- Avatar preview -->
                <div class="avatar-section mb-4">
                    <div class="avatar-preview">
                        @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                        {
                            <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <div class="avatar-url-display">
                        <label class="form-label text-muted small">Avatar URL</label>
                        <input type="url" class="form-control form-control-sm" @bind="_avatarUrl"
                               placeholder="https://example.com/avatar.jpg" />
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" placeholder="Your display name" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_email" placeholder="you@example.com" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio" placeholder="Tell us about yourself..."></textarea>
                </div>

                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="SaveProfile" disabled="@(!ProfileHasChanges)">
                        Save Changes
                    </button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges" disabled="@(!ProfileHasChanges)">
                        Discard Changes
                    </button>
                </div>
            </div>
        </div>
    };

    // ===================== NOTIFICATIONS =====================

    private void LoadNotificationState(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;

        _channels = _allChannels.Select(ch => new ChannelMuteState
        {
            Name = ch,
            Muted = prefs.MutedChannels.Contains(ch)
        }).ToList();
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved.");
    }

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h3 class="section-title">Notifications</h3>

        <div class="card settings-card">
            <div class="card-body">
                <h6 class="mb-3">General</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>

                <div class="form-check form-switch mb-4">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>

                <hr />

                <h6 class="mb-3">Muted Channels</h6>
                <div class="channel-list">
                    @foreach (var channel in _channels)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input darker-border-checkbox" type="checkbox"
                                   id="ch-@channel.Name" @bind="channel.Muted" />
                            <label class="form-check-label" for="ch-@channel.Name">
                                #@channel.Name
                            </label>
                        </div>
                    }
                </div>

                <div class="mt-4">
                    <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            </div>
        </div>
    };

    // ===================== SECURITY =====================

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", isError: true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            ShowToast("New password must be at least 8 characters.", isError: true);
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            ShowToast("Password updated successfully.");

            // Reload security settings to get updated LastPasswordChange
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        catch (Exception ex)
        {
            ShowToast(ex.Message, isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked successfully.");
        }
        catch (Exception ex)
        {
            ShowToast(ex.Message, isError: true);
        }
        finally
        {
            _revoking = false;
            _showRevokeConfirm = false;
            _sessionToRevoke = null;
        }
    }

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h3 class="section-title">Security</h3>

        <!-- Change Password -->
        <div class="card settings-card mb-3">
            <div class="card-header expandable-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <div class="d-flex justify-content-between align-items-center">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </div>
            </div>
            @if (_changePasswordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_changingPassword">
                        @if (_changingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Update Password
                    </button>
                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <small class="text-muted ms-3">
                            Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                        </small>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card settings-card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_securitySettings?.TwoFactorEnabled == true ? "bg-success" : "bg-secondary")">
                            @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@(_securitySettings?.TwoFactorEnabled ?? false)"
                               disabled
                               title="Contact your administrator to change 2FA settings" />
                    </div>
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card settings-card">
            <div class="card-body">
                <h6 class="mb-3">Active Sessions</h6>
                @if (_securitySettings?.Sessions.Count > 0)
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th class="text-end">Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _securitySettings.Sessions)
                                {
                                    var isCurrent = session == _securitySettings.Sessions.First();
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrent)
                                            {
                                                <span class="badge bg-primary ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("MMM dd, yyyy h:mm tt")</td>
                                        <td class="text-end">
                                            @if (!isCurrent)
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => RequestRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted mb-0">No active sessions found.</p>
                }
            </div>
        </div>
    };

    // ===================== APPEARANCE =====================

    private void LoadAppearanceState(AppearanceSettings settings)
    {
        _appearanceSettings = settings;
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        ShowToast("Appearance settings saved.");
    }

    private string PreviewFontSizeClass => _fontSize switch
    {
        "Small" => "preview-font-small",
        "Large" => "preview-font-large",
        _ => "preview-font-medium"
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h3 class="section-title">Appearance</h3>

        <div class="card settings-card mb-3">
            <div class="card-body">
                <!-- Theme -->
                <h6 class="mb-3">Theme</h6>
                <div class="d-flex gap-3 mb-4">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var themeVal = theme;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="theme-@themeVal" value="@themeVal"
                                   checked="@(_theme == themeVal)"
                                   @onchange="() => _theme = themeVal" />
                            <label class="form-check-label" for="theme-@themeVal">@themeVal</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <h6 class="mb-3">Font Size</h6>
                <div class="d-flex gap-3 mb-4">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var sizeVal = size;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="font-@sizeVal" value="@sizeVal"
                                   checked="@(_fontSize == sizeVal)"
                                   @onchange="() => _fontSize = sizeVal" />
                            <label class="form-check-label" for="font-@sizeVal">@sizeVal</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6 class="mb-2">Language</h6>
                    <select class="form-select" style="max-width: 300px;"
                            @bind="_language">
                        @foreach (var lang in _availableLanguages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="form-check form-switch mb-4">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>

                <hr />

                <!-- Live Preview -->
                <h6 class="mb-3">Preview</h6>
                <div class="live-preview @(_theme == "Dark" ? "preview-dark" : "preview-light") @PreviewFontSizeClass @(_compactMode ? "preview-compact" : "")">
                    <div class="preview-header">
                        <strong>Sample Header</strong>
                        <span class="preview-badge">@_theme Theme</span>
                    </div>
                    <p class="preview-text">
                        This is a preview of how your content will look with the selected settings.
                        Font size is set to <strong>@_fontSize</strong> and language is <strong>@_language</strong>.
                    </p>
                    <div class="preview-actions">
                        <span class="preview-btn preview-btn-primary">Primary</span>
                        <span class="preview-btn preview-btn-secondary">Secondary</span>
                    </div>
                </div>

                <div class="mt-4">
                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </div>
        </div>
    };

    // ===================== HELPERS =====================

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
    }
}
"}

